      "content": "项目交接卡不是简单记录，而是 Growth OS 的工作接力文件。每天结束时，把今日完成、关键结论、问题、下一步和 AI 上下文接力整理成固定格式。下一次打开 Codex 或 ChatGPT 时，先读取交接卡，就能快速恢复项目现场，减少重复解释和上下文丢失。",
