      "title": "蓝V账号承接 SOP",
      "type": "sop",
      "date": "2026-07-23",
      "summary": "蓝V账号权重更高，适合承接更多私信，但历史异常账号仍可能持续触发风控。",
      "content": "蓝V账号权重通常高于普通账号，每天可承接更多私信；每个人可验证多个蓝V账号。但如果某个蓝V账号之前出现过关注、私信或风控问题，后续仍可能频繁异常，需要单独记录和隔离。",
