      "title": "评论引流基础动作 SOP",
      "type": "sop",
      "date": "2026-07-23",
      "summary": "评论引流的核心是引起对方注意并降低信任成本，而不是在评论区完成完整沟通。",
      "content": "引流动作可先对目标账号作品做随机点赞和收藏，再评论一句低压提示，如“你好美女，看你在我大号下面评论了，那边回不了你，这边回关一下。”评论后关注对方，等待回关，不要继续做多余动作。",
