      "date": "2026-07-23",
      "summary": "用途：统一记录抖音视频基准数据，沉淀运营规律，形成长期视频数据库。；Step1 基础信息；视频编号",
      "content": "工作流交接卡\n视频基准库工作流 V2.0\n用途：统一记录抖音视频基准数据，沉淀运营规律，形成长期视频数据库。\nStep1 基础信息\n视频编号\n发布时间\n内容方向\n内容形式\n封面标题\n视频时长\nStep2 原始数据\n播放量\n涨粉\n点赞\n评论\n收藏\n分享\nStep3 留存数据（重点）\n2秒跳出率\n5秒完播率\n完播率\n平均播放时长\n平均播放占比\nStep4 互动数据\n点赞率\n评论率\n收藏率\n分享率\n不感兴趣率\nStep5 流量来源\n推荐页\n个人主页\n搜索\n关注\n合集\n其他\nStep6 搜索关键词\n记录搜索词\nStep7 AI运营备注\n内容类型\n封面特点\n数据亮点\n存在问题\n可验证结论\n后续优化建议\nStep8 标签\n内容标签\n部位标签\n数据标签\n输出标准\n视频基准记录\nAI运营备注\n标签\n可加入数据库的运营规律\n长期目标\n累计100-300条视频后，进行爆款规律、内容形式、封面标题、留存、推荐机制、搜索流量等交叉分析，沉淀医美运营方法论。\n\n原始文件：视频基准库\\视频基准库工作流V2.0_交接卡.docx",
