      "content": "本次实验验证视频数据的公开展示方式：\n1. 视频数据库是主库，保存 77 条完整视频样本。\n2. 公开视频页默认展示前 25 条，也就是约前三分之一样本，方便外部查看。\n3. 输入密码后展示完整 77 条表格，而不是只展开某一条隐藏数据。\n4. 实验库只保存实验结论和展示策略，具体样本仍回到视频数据库查看。\n5. 项目阶段总览只标记阶段变化；视频样本新增属于库更新，不等于项目阶段变化。",
