      "id": "derived-rule-specific-body-part-title-2026-07-27",
      "title": "具体部位标题比泛泛变美更容易承接搜索需求",
      "type": "rule",
      "date": "2026-07-27",
      "summary": "前 25 条样本里，大腿、腰腹、背部、手臂、臀部等具体部位，会自然带出价格、适配、恢复和效果问题。",
      "content": "视频主题越具体，后续搜索词和需求越容易落到可回答的问题上。比如大腿环吸、手臂塑形、腰腹环吸、妈妈臀、直角肩，会带出价格、适配体型、恢复期、反弹凹凸和技术区别。这类内容更适合沉淀成选题模型和评论承接话术。",
