      "id": "feishu-active-account-matrix-assistant-sop",
      "title": "运营SOP：活跃账号、矩阵号与助理号分工",
      "type": "sop",
      "date": "2026-07-28",
      "summary": "活跃账号负责养号和引流文案，矩阵号负责流量入口，助理号负责承接和转换。",
      "content": "提炼结论：账号体系不是单号打法，而是分工系统。活跃账号先养到 150-160 粉丝再发引流文案；矩阵号隐藏粉丝/关注/收藏并避免白大褂头像；助理号用医生图片和生活内容承接，引导加微。\n\n原文记录：\n活跃账号，加矩阵号\n活跃账号\n发引流文案\n上午点关注，点粉丝\n中午点关注，粉丝\n晚上挂直播，抢福袋\n粉丝量达到150到160之间\n发引流文案\n矩阵号\n把粉丝列表，关注，收藏全隐藏\n头像不能白大褂\n背景换成（不能白大褂）本人头像加一句\n话，例如：不停的雕琢，只为遇见更好的自己\n助理号\n名字-几号\n聊几句就加微，本质是为了引流转换\n主要转换的，发医生图片\n发日常吃饭，风景\n用那个微信作品转发引流，让对方加我们\n尝试微信",
