      "id": "feishu-matrix-main-account-comment-sop",
      "title": "矩阵主账号：评论与回关处理SOP",
      "type": "sop",
      "date": "2026-07-28",
      "summary": "有评论先关注、点赞、回问题；回关后两轮内发话术，遇到安全验证直接放弃。",
      "content": "提炼结论：矩阵主账号的评论处理要快，但不能冒险。先做关注、点赞和问题回复；判断真人和异常账号；回关后两轮内承接；出现安全验证就停止。\n\n原文记录：\n矩阵主账号\n有评论第一时间，点关注，电赞两个➕回评论，回他的问题，你想了解什么\n主动关注我们：查看粉丝列表和关注列表有没有医生，判断是不是真人，真人作品出现，有可能是医托或者很难缠\n回关了，之后两轮就直接不管，发话术，表情包加仅一次观看\n第二次就回表情包\n有的账号出现安全验证就不要去回了，直接放弃，因为会出现安全验证，说明出问题了，虽然不明白哪里出问题了，这里一定要万分小心",
