      "summary": "沉淀邵红伟医生素材的画质、音频、美颜、美体、色彩和 HSL 参数。",
      "content": "提炼结论：人物参数库用于保证同一医生素材的画面稳定性。核心包括高清画质、音量最大、降噪、声道配置、美颜美体、基础色彩和肤色 HSL 调整。\n\n原文记录：\n邵红伟人物参数\n画面 基础\n超清画质：高清\n音频\n音量：20开到最大\n音频降噪开\n声道配置：防止只有一个声道\n画面美颜美体\n磨皮40\n匀肤40\n去法令纹60\n去黑眼圈60\n清晰10\n流畅脸30\n小脸10\n廋脸10\n发际线10\n大眼30\n亮眼30\n美妆男生\n调整基础\n色温：-5\n自然饱和度：30\n亮度：5\n对比度：10\n阴影：-10\n光感：5\n锐化：15\n清晰：20\n调整hsl\n红圈\n色相10\n饱和度9\n亮度15\n肤色黄圈\n色相10\n饱和度9\n亮度15",
