      "id": "feishu-operation-risk-limit-flow-summary",
      "title": "风险总结：私信、限流与前期互动边界",
      "type": "risk",
      "date": "2026-07-28",
      "summary": "未回关不要私信；限流视频第一时间隐藏；前期不要急着回复和私信，等主动私信再承接。",
      "content": "提炼结论：前期账号保护大于转化速度。没有回关不要私信；作品限流后马上隐藏；前期评论区回答即可，不要急；等到一百多粉丝且有人主动私信后再承接。\n\n原文记录：\n问题总结\n1.不要在别人没有回关的时候去私信其他人\n2.矩阵账号发了视频间隔几个小时看一下，作品分析，有没有限流，限流了就直接隐藏，不要去再跑流量，因为会屡次不改会被封\n在同事发了八个视频之后，直接就被封号一个月，这是不能接受的（查看方法，手机版，在每个视频下面点进去有个作品分析，然后查看是不是有显示限制流量，只让自己查看，如果被限流，第一时间就把作品隐藏，不要管了）\n前期不要去回复，评论区回答，不要着急，差不多一百多粉丝之后，有人主动私信再说",
