      "content": "候选规律\n前三秒不是单纯吸引注意力，而是要让用户快速看懂：这条内容和自己有什么关系、能带来什么结果。\n\n对应链路\n满足需求 → 产生价值 → 触发行为 → 获得推荐\n\n当前判断\n如果封面和前三秒能够激活用户需求，用户更可能继续看、评论、点赞或私信。平台识别到这些行为后，推荐扩大概率会上升。\n\n状态\n候选规律。还需要用多次视频样本和运营实验继续验证，不能直接当成长期规律。",
